class Test {
    static class A {}
    static A A = new A();
    void f() {
        class B {}
        B B = new B();
    }
}
EOF
javac /tmp/Test.java 2>&1; echo javac:$?
if command -v kotlinc >/dev/null; then cat >/tmp/Test.kt <<'EOF'
class A
val A = A()

class C {
